 1492 |     pub fn candidates(self: *TrigramIndex, query: []const u8, allocator: std.mem.Allocator) ?[]const []const u8 {
 1493 |         if (query.len < 3) return null;
 1494 | 
 1495 |         const tri_count = query.len - 2;
 1496 | 
 1497 |         var unique = std.AutoHashMap(Trigram, void).init(allocator);
 1498 |         defer unique.deinit();
 1499 |         unique.ensureTotalCapacity(@intCast(tri_count)) catch return null;
 1500 |         for (0..tri_count) |i| {
 1501 |             const tri = packTrigram(
 1502 |                 normalizeChar(query[i]),
 1503 |                 normalizeChar(query[i + 1]),
 1504 |                 normalizeChar(query[i + 2]),
 1505 |             );
 1506 |             _ = unique.getOrPut(tri) catch return null;
 1507 |         }
 1508 | 
 1509 |         var sets: std.ArrayList(*PostingList) = .empty;
 1510 |         defer sets.deinit(allocator);
 1511 |         sets.ensureTotalCapacity(allocator, unique.count()) catch return null;
 1512 | 
 1513 |         var tri_iter = unique.keyIterator();
 1514 |         while (tri_iter.next()) |tri_ptr| {
 1515 |             const posting_list = self.index.getPtr(tri_ptr.*) orelse {
 1516 |                 return allocator.alloc([]const u8, 0) catch null;
 1517 |             };
 1518 |             sets.appendAssumeCapacity(posting_list);
 1519 |         }
 1520 | 
 1521 |         if (sets.items.len == 0) {
 1522 |             return allocator.alloc([]const u8, 0) catch null;
 1523 |         }
 1524 | 
 1525 |         // Sort posting lists by size (smallest first) for efficient intersection
 1526 |         std.mem.sort(*PostingList, sets.items, {}, struct {
 1527 |             fn lt(_: void, a: *PostingList, b: *PostingList) bool {
 1528 |                 return a.items.items.len < b.items.items.len;
 1529 |             }
 1530 |         }.lt);
 1531 | 
 1532 |         // Sorted merge intersection: start with smallest list's doc_ids
 1533 |         var result_ids: std.ArrayList(u32) = .empty;
 1534 |         defer result_ids.deinit(allocator);
 1535 | 
