 1537 |         result_ids.ensureTotalCapacity(allocator, sets.items[0].items.items.len) catch return null;
 1538 |         for (sets.items[0].items.items) |p| {
 1539 |             result_ids.appendAssumeCapacity(p.doc_id);
 1540 |         }
