 1542 |         // Intersect with each subsequent list (both sorted → merge O(n+m))
 1543 |         for (sets.items[1..]) |set| {
 1544 |             var write: usize = 0;
 1545 |             var si: usize = 0;
 1546 |             const set_items = set.items.items;
