 1549 |                 while (si < set_items.len and set_items[si].doc_id < id) : (si += 1) {}
 1550 |                 if (si < set_items.len and set_items[si].doc_id == id) {
 1551 |                     result_ids.items[write] = id;
 1552 |                     write += 1;
 1553 |                     si += 1;
 1554 |                 }
 1555 |             }
 1556 |             result_ids.items.len = write;
