            }
        }
    }
    fn indexOneToken(
        self: *WordIndex,
        token: []const u8,
        doc_id: u32,
        line_num: u32,
        words_set: ?*std.StringHashMap(void),
    ) !void {
        const gop = try self.index.getOrPut(token);
        if (!gop.found_existing) {
            // A failed dupe must take the fresh entry with it — the key still
            // points at the tokenizer's stack buffer and the value is
            // undefined; left in place, the next insert that lands on it
            // dereferences garbage.
            const duped = self.allocator.dupe(u8, token) catch |err| {
                _ = self.index.remove(token);
                return err;
            };
            gop.key_ptr.* = duped;
            gop.value_ptr.* = .empty;
        }
        if (gop.value_ptr.items.len > 0) {
            const last = gop.value_ptr.items[gop.value_ptr.items.len - 1];
            if (last.doc_id == doc_id and last.line_num == line_num) {
                if (words_set) |set| {
                    const wgop = try set.getOrPut(gop.key_ptr.*);
                    if (!wgop.found_existing) wgop.key_ptr.* = gop.key_ptr.*;
                }
                return;
            }
        }
        try gop.value_ptr.append(self.allocator, .{
            .doc_id = doc_id,
            .line_num = line_num,
        });
        if (words_set) |set| {
            const wgop = try set.getOrPut(gop.key_ptr.*);
            if (!wgop.found_existing) wgop.key_ptr.* = gop.key_ptr.*;
        }
    }

